import { useRef, useState } from "react";

import ULThemeCard from "@/components/ULThemeCard";
import ULThemePageLayout from "@/components/ULThemePageLayout";

import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import Footer from "./components/Footer";
import LeftPanel from "./components/LeftPanel";
import LoginIdForm from "./components/LoginIdForm";
import { useLoginIdManager } from "./hooks/useLoginIdManager";

function LoginIdScreen() {
  // Extracting attributes from hook made out of LoginIdInstance class of Auth0 React ACUL SDK
  const { loginId, texts, locales } =
    useLoginIdManager();

  // Other Texts
  document.title = texts?.pageTitle || locales?.page?.title;

  applyAuth0Theme(loginId);

  const [leftWidth, setLeftWidth] = useState(50);
  const isDragging = useRef(false);
  const panelRowRef = useRef<HTMLDivElement>(null);

  const handleDividerMouseDown = (e: React.MouseEvent) => {
    e.preventDefault();
    isDragging.current = true;

    const onMouseMove = (e: MouseEvent) => {
      if (!isDragging.current || !panelRowRef.current) return;
      const rect = panelRowRef.current.getBoundingClientRect();
      const pct = ((e.clientX - rect.left) / rect.width) * 100;
      setLeftWidth(Math.min(70, Math.max(30, pct)));
    };

    const onMouseUp = () => {
      isDragging.current = false;
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
  };


  return (
    // Applying UDS theme overrides using the "theme-universal" class
    <ULThemePageLayout className="theme-universal p-0 items-stretch">
      <div style={{ display: "flex", flexDirection: "column", width: "100%", minWidth: "680px", height: "100vh", overflow: "hidden", backgroundColor: "#ffffff" }}>
        <div style={{ flexShrink: 0, padding: "1.25rem 2rem", borderBottom: "1px solid #e5e7eb", backgroundColor: "#f3f4f6", textAlign: "center" }}>
          <span style={{ fontWeight: 700, fontSize: "1.125rem", color: "#111827" }}>Join Now</span>
        </div>
        <div ref={panelRowRef} style={{ display: "flex", flex: 1, overflow: "hidden" }}>
          <div style={{ width: `${leftWidth}%`, flexShrink: 0, height: "100%" }}>
            <LeftPanel />
          </div>
          <div
            onMouseDown={handleDividerMouseDown}
            style={{ width: "5px", cursor: "col-resize", backgroundColor: "#e5e7eb", flexShrink: 0 }}
          />
          <div style={{ flex: 1, overflowY: "auto", padding: "1rem 4rem 2.5rem 1.5rem", backgroundColor: "#ffffff" }}>
            <ULThemeCard className="w-full max-w-[400px] gap-0 px-6" style={{ border: "none", boxShadow: "none", borderRadius: 0, backgroundColor: "transparent" }}>
              <LoginIdForm />
              <Footer />
              
            </ULThemeCard>
          </div>
        </div>
      </div>
    </ULThemePageLayout>
  );
}

export default LoginIdScreen;
